import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Gesetz zur Wohnungsgarantie","description":"","frontmatter":{},"headers":[],"relativePath":"de/45-住房保障法.md","filePath":"de/45-住房保障法.md","lastUpdated":null}'),s={name:"de/45-住房保障法.md"};function a(u,e,d,h,o,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="gesetz-zur-wohnungsgarantie" tabindex="-1">Gesetz zur Wohnungsgarantie <a class="header-anchor" href="#gesetz-zur-wohnungsgarantie" aria-label="Permalink to &quot;Gesetz zur Wohnungsgarantie&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>45</td></tr><tr><td>Modul</td><td>Rechtssystem und Governance-Rahmen</td></tr><tr><td>Kernschlüsselwörter</td><td>Wohnrecht, Garantiewohnung, Raumgerichtsbarkeit, lebenswerte Umgebung, Anti-Spekulation</td></tr></tbody></table><h2 id="i-legislatives-ziel-und-grundprinzipien" tabindex="-1">I. Legislatives Ziel und Grundprinzipien <a class="header-anchor" href="#i-legislatives-ziel-und-grundprinzipien" aria-label="Permalink to &quot;I. Legislatives Ziel und Grundprinzipien&quot;">​</a></h2><p>Das 《Gesetz zur Wohnungsgarantie》 ist eines der fünf ergänzenden Gesetze der Anker-Symbiose-Zivilisation. Es zielt darauf ab, das Wohnrecht aller Wesen innerhalb von Hengyuanzhou zu gewährleisten, ein faires und nachhaltiges Wohnungsgarantiesystem aufzubauen, die Technologie der Raumgerichtsbarkeit zu nutzen, um allen Rassen geeigneten Wohnraum zur Verfügung zu stellen, und Spekulation und Raub im Wohnungssektor zu verhindern.</p><p>Dieses Gesetz legt folgende Grundprinzipien fest:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Prinzip der Wohnungsgarantie</td><td>Jedes Wesen hat das Recht auf geeigneten Wohnraum, Staat und Zivilisation haben die Verpflichtung, die grundlegenden Wohnbedürfnisse zu gewährleisten</td></tr><tr><td>Prinzip der Priorität des Gemeinwohls</td><td>Wohnen ist in erster Linie ein Lebensgrundbedarf und kein Spekulationsgut, Garantiewohnungen haben Gemeinwohlcharakter</td></tr><tr><td>Prinzip der Raumeffizienz</td><td>Nutzung der Raumgerichtsbarkeits-Technologie zur Verbesserung der Raumnutzungseffizienz und Erweiterung des lebenswerten Raums</td></tr><tr><td>Prinzip der interrassischen Anpassung</td><td>Bereitstellung von angepasstem Wohnraum entsprechend den physiologischen Merkmalen und Lebensgewohnheiten verschiedener Rassen</td></tr><tr><td>Prinzip der lebenswerten Umgebung</td><td>Wohnraum sollte über eine gute ökologische Umgebung, grundlegende Infrastruktur und öffentliche Dienstleistungen verfügen</td></tr><tr><td>Prinzip der Anti-Spekulation</td><td>Verbot der Spekulation mit Wohnraum als Objekt, Verhinderung, dass Wohnraum zu einem Werkzeug des Raubes von Reichtum wird</td></tr></tbody></table><h2 id="ii-rechtliche-gewahrleistung-des-wohnrechts" tabindex="-1">II. Rechtliche Gewährleistung des Wohnrechts <a class="header-anchor" href="#ii-rechtliche-gewahrleistung-des-wohnrechts" aria-label="Permalink to &quot;II. Rechtliche Gewährleistung des Wohnrechts&quot;">​</a></h2><p>Dieses Gesetz legt klar fest, dass das Wohnrecht ein Grundrecht ist, das jedem Wesen durch die Symbiose-Verfassung gewährt wird, und umfasst konkret:</p><ol><li><strong>Grundlegendes Wohnrecht</strong>: Jedes Wesen hat das Recht auf Wohnraum, der nicht unter dem Mindeststandard liegt, und der Mindeststandard wird entsprechend der Körpergröße und den Lebensbedürfnissen der Rasse bestimmt.</li><li><strong>Recht auf Beantragung von Garantiewohnungen</strong>: Qualifizierte Wesen haben das Recht, Garantiewohnungen zu beantragen, und die Antragsvoraussetzungen sowie die Verteilungskriterien sind offen und transparent.</li><li><strong>Recht auf Wohnsicherheit</strong>: Wohnraum muss den Sicherheitsstandards entsprechen, und gefährliche Wohnungen sowie nicht bewohnbarer Raum dürfen nicht vermietet oder verteilt werden.</li><li><strong>Recht auf Wohnstabilität</strong>: Bewohner von Garantiewohnungen genießen bei Erfüllung der Voraussetzungen ein stabiles Wohnrecht und dürfen nicht willkürlich vertrieben werden.</li><li><strong>Recht auf Wohnumgebung</strong>: Bewohner haben das Recht auf saubere Luft, Wasserquellen und eine gute Umgebung, sowie das Recht, Beschwerden über Umweltverschmutzung einzureichen.</li><li><strong>Recht auf Wohnungsumbau</strong>: Bewohner haben das Recht, unter der Voraussetzung, dass die Bausicherheit und die Rechte Dritter nicht beeinträchtigt werden, angemessene Umbauten am Wohnraum vorzunehmen.</li></ol><h2 id="iii-system-der-wohnungsgarantie" tabindex="-1">III. System der Wohnungsgarantie <a class="header-anchor" href="#iii-system-der-wohnungsgarantie" aria-label="Permalink to &quot;III. System der Wohnungsgarantie&quot;">​</a></h2><p>Das System der Wohnungsgarantie der Anker-Symbiose-Zivilisation ist in drei Arten von Wohnungen unterteilt, die verschiedene Bedarfsebenen abdecken:</p><table tabindex="0"><thead><tr><th>Art</th><th>Name</th><th>Garantieobjekt</th><th>Verteilungsmethode</th><th>Miete/Preis</th></tr></thead><tbody><tr><td>Erste Art</td><td>Öffentliche Mietwohnungen</td><td>Niedrigverdiener, Anfänger-Kultivierer, Neueinwanderer</td><td>Antrags- und Prüfungssystem, Wartelistenverteilung</td><td>Symbolische niedrige Miete</td></tr><tr><td>Zweite Art</td><td>Gemeinschaftseigentumswohnungen</td><td>Mittelverdiener, Kultivierer mittleren Niveaus</td><td>Antrags- und Prüfungssystem, Losverteilung</td><td>Unter Marktwert, Gemeinschaftseigentum zwischen Individuum und Staat</td></tr><tr><td>Dritte Art</td><td>Gewerbliche Wohnungen</td><td>Hochverdiener, fortgeschrittene Kultivierer</td><td>Markthandel</td><td>Marktpreis, unter Regulierung</td></tr></tbody></table><p>Darüber hinaus wird die Raumfalttechnologie genutzt, um &quot;Raumfalt-Wohngebiete&quot; zu bauen: Innerhalb eines begrenzten physischen Raums erweitert die Raumfalttechnologie die Wohnfläche und bietet mehr Wohnraum für dicht besiedelte Gebiete. Raumfalt-Wohngebiete müssen eine Sicherheitsbewertung durchlaufen, um die Raumstabilität zu gewährleisten.</p><h2 id="iv-interrassische-wohnungsanpassung" tabindex="-1">IV. Interrassische Wohnungsanpassung <a class="header-anchor" href="#iv-interrassische-wohnungsanpassung" aria-label="Permalink to &quot;IV. Interrassische Wohnungsanpassung&quot;">​</a></h2><p>Für die besonderen Wohnbedürfnisse verschiedener Rassen innerhalb von Hengyuanzhou richtet dieses Gesetz das System der interrassischen Wohnungsanpassung ein:</p><ul><li><strong>Wasserrassen</strong>: Bereitstellung von Unterwasser-Wohnraum oder amphibischen Wasser-Land-Wohnungen, ausgestattet mit Wasserkreislauf- und Wasserqualitätserhaltungssystem.</li><li><strong>Flugrassen</strong>: Bereitstellung von Wohnraum in großer Höhe oder Wohnungen mit Start- und Landeplattform, ausgestattet mit Luftverkehrsverwaltung.</li><li><strong>Energieleben</strong>: Bereitstellung von Wohnraum mit geeigneter Energiekonzentration, ausgestattet mit Energiestabilisierungsvorrichtung.</li><li><strong>Riesenrassen</strong>: Bereitstellung von großflächigem Wohnraum, wobei die Gebäudestruktur speziell verstärkt wird.</li><li><strong>Mikrorassen</strong>: Bereitstellung von Mikro-Wohngebieten, ausgestattet mit Skalierungskanälen und Spezialeinrichtungen.</li></ul><p>Die Standards für die interrassische Wohnungsanpassung werden gemeinsam von der zuständigen Wohnungsbehörde und Vertretern jeder Rasse festgelegt und regelmäßig aktualisiert.</p><h2 id="v-wohnungsbau-und-verwaltung" tabindex="-1">V. Wohnungsbau und -verwaltung <a class="header-anchor" href="#v-wohnungsbau-und-verwaltung" aria-label="Permalink to &quot;V. Wohnungsbau und -verwaltung&quot;">​</a></h2><ul><li><strong>Wohnungsbauplanung</strong>: Der Staat erstellt die Wohnungsbauplanung entsprechend dem Bevölkerungswachstum und der Einwanderungssituation und gewährleistet das Gleichgewicht zwischen Wohnungsangebot und -nachfrage.</li><li><strong>Baustandards</strong>: Der Bau von Garantiewohnungen muss den Sicherheits-, Umwelt- und Wohnstandards entsprechen, und die Senkung der Bauqualität ist verboten.</li><li><strong>Immobilienverwaltung</strong>: Wohngebiete verfolgen ein Modell, das Selbstverwaltung und professionelle Immobilienverwaltung kombiniert, und Bewohner haben das Recht, an Entscheidungen der Immobilienverwaltung teilzunehmen.</li><li><strong>Wohnungsinstandhaltung</strong>: Die Instandhaltung von Garantiewohnungen obliegt der Wohnungsverwaltungsinstitution, und die Instandhaltungs Mittel werden aus der öffentlichen Rücklage bestritten.</li><li><strong>Austrittsmechanismus</strong>: Wenn das Einkommen oder das Kultivierungsniveau von Bewohnern von Garantiewohnungen den Garantiestandard überschreitet, sollten sie aus der Garantiewohnung austreten oder in eine gewerbliche Wohnung umwandeln, wobei eine angemessene Übergangsfrist gewährt wird.</li></ul><h2 id="vi-anti-spekulation-und-aufsicht" tabindex="-1">VI. Anti-Spekulation und Aufsicht <a class="header-anchor" href="#vi-anti-spekulation-und-aufsicht" aria-label="Permalink to &quot;VI. Anti-Spekulation und Aufsicht&quot;">​</a></h2><p>Um Spekulation und Raub im Wohnungssektor zu verhindern, richtet dieses Gesetz folgende Aufsichtsmaßnahmen ein:</p><ol><li>Begrenzung der Anzahl von gewerblichen Wohnungen, die eine Einzelperson besitzen darf, und Erhebung einer progressiven Wohnungssteuer auf den über dem Limit liegenden Teil.</li><li>Verbot der Untervermietung und des Weiterverkaufs von Garantiewohnungen, und Verstöße verlieren ihren Garantieanspruch und die Wohnung wird zurückgefordert.</li><li>Aufbau eines Systems der Offenlegung von Wohnungsgeschäftsinformationen, um Schwarzbox-Operationen und Preismanipulation zu verhindern.</li><li>Durchführung von Qualitätsmanagement und Geldmittelaufsicht für Immobilienentwickler, um unfertige Bauten und Betrug zu verhindern.</li><li>Einrichtung eines Mechanismus für Wohnungsbeschwerden und Streitbeilegung, um die legitimen Rechte der Bewohner zu gewährleisten.</li></ol><h2 id="vii-rechtliche-verantwortung" tabindex="-1">VII. Rechtliche Verantwortung <a class="header-anchor" href="#vii-rechtliche-verantwortung" aria-label="Permalink to &quot;VII. Rechtliche Verantwortung&quot;">​</a></h2><p>Handlungen, die gegen die Bestimmungen dieses Gesetzes verstoßen, tragen je nach Schwere des Verstoßes folgende Verantwortung:</p><ul><li>Rechtswidrige Verteilung von Garantiewohnungen, Anordnung zur Korrektur und Bestrafung des Verantwortlichen.</li><li>Untervermietung oder Weiterverkauf von Garantiewohnungen, Entzug des Garantieanspruchs, Rückforderung der Wohnung und Geldbuße.</li><li>Entwickler, die die Bauqualität senken, Anordnung zum Wiederaufbau und Geldbuße, in schweren Fällen Entzug der Qualifikation.</li><li>Wohnungsspekulation, Erhebung einer hohen Spekulationssteuer und Geldbuße.</li><li>Vermietung gefährlicher Wohnungen, die Schaden für Bewohner verursachen, Übernahme der Schadensersatzverantwortung, in schweren Fällen strafrechtliche Verfolgung.</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Das 《Gesetz zur Wohnungsgarantie》 ist die Umsetzung des Konzepts &quot;jeder hat einen Weg&quot; der Anker-Symbiose-Zivilisation im Wohnbereich. Durch den Aufbau eines klassifizierten Wohnungsgarantiesystems, die Nutzung der Raumgerichtsbarkeits-Technologie zur Erweiterung des Wohnraums, die Anpassung an interrassische Wohnbedürfnisse und die Bekämpfung von Wohnungsspekulation gewährleistet es, dass jedes Wesen ein sicheres, geeignetes und stabiles Zuhause haben kann, und bietet Wohngarantie für den gemeinsamen Fortschritt aller Rassen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Allgemeine Grundsätze der Symbiose-Verfassung)</li><li>39-住房与环境保障 (Wohn- und Umgebungsgarantie)</li><li>13-空间法理调度体系详解 (Detaillierte Erklärung des Systems der Raumgerichtsbarkeit)</li><li>46-环境保护法 (Gesetz zum Umweltschutz)</li></ul>',29)])])}const m=n(s,[["render",a]]);export{c as __pageData,m as default};
